// The State field; a superseded entry names its successor in superseded_by.
enum class State : std::uint8_t { Active, Withdrawn, Superseded };
// A Switch: name's form: a BOF3X_ORIGINAL name (key = the name), ini:<key>=<value>,
// env:<BOF3X_NAME>=<value> (an empty value means unset), or lang (the language box).
