// The switches of one entry.
constexpr const Switch* SwitchesBegin(const Entry& e) { return kSwitches + e.first_switch; }
constexpr const Switch* SwitchesEnd(const Entry& e) { return kSwitches + e.first_switch + e.switch_count; }
// Whether the language pick governs the entry (its Languages is a list, not any).
constexpr bool LanguageGoverned(const Entry& e) { return e.languages != kLangAny; }
// Whether the entry acts under a language (one kLang* bit).
constexpr bool ActsUnder(const Entry& e, std::uint8_t lang) {
    return e.languages == kLangAny || (e.languages & lang) != 0;
}
// The entry for DIV-id, or nullptr.
constexpr const Entry* Find(std::uint16_t id) {
    for (const Entry& e : kEntries)
        if (e.id == id) return &e;
    return nullptr;
}

// The table is whole: ids rise, every entry's switches lie inside kSwitches.
constexpr bool TableIsWhole() {
    std::size_t next = 0;
    for (std::size_t i = 0; i < kEntryCount; ++i) {
        if (i > 0 && kEntries[i].id <= kEntries[i - 1].id) return false;
        if (kEntries[i].first_switch != next) return false;
        next += kEntries[i].switch_count;
    }
    for (const Switch& s : kSwitches)
        if (s.key_len == 0 || s.key_at + s.key_len > s.text.size()) return false;
    return next == kSwitchCount;
}
static_assert(TableIsWhole(), "ledger_registry.h: regenerate with tools/ledger_registry.py");

